def semver_sort(versions):
    def parse(v):
        core = v
        pre = None
        if '+' in core:
            core = core.split('+', 1)[0]
        if '-' in core:
            core, pre = core.split('-', 1)
        major, minor, patch = (int(x) for x in core.split('.'))
        pre_ids = pre.split('.') if pre is not None else None
        return (major, minor, patch, pre_ids)

    def pre_key(pre_ids):
        if pre_ids is None:
            return None
        key = []
        for ident in pre_ids:
            if ident.isdigit():
                key.append((0, int(ident), ''))
            else:
                key.append((1, 0, ident))
        return key

    def cmp_pre(a, b):
        if a is None and b is None:
            return 0
        if a is None:
            return 1
        if b is None:
            return -1
        ka = pre_key(a)
        kb = pre_key(b)
        for x, y in zip(ka, kb):
            if x < y:
                return -1
            if x > y:
                return 1
        if len(ka) < len(kb):
            return -1
        if len(ka) > len(kb):
            return 1
        return 0

    import functools

    def cmp(v1, v2):
        m1, n1, p1, pre1 = parse(v1)
        m2, n2, p2, pre2 = parse(v2)
        if (m1, n1, p1) != (m2, n2, p2):
            return -1 if (m1, n1, p1) < (m2, n2, p2) else 1
        return cmp_pre(pre1, pre2)

    return sorted(versions, key=functools.cmp_to_key(cmp))

